// --- Royal UI palette ---
#define ROYAL_GOLD      GOLD
#define ROYAL_GOLD_DIM  (Color){ 146, 116, 63, 220 }

static Color ScaleColor(Color c, float k) {
    Color r = c;
    r.r = (unsigned char)(c.r * k > 255.0f ? 255 : c.r * k);
    r.g = (unsigned char)(c.g * k > 255.0f ? 255 : c.g * k);
    r.b = (unsigned char)(c.b * k > 255.0f ? 255 : c.b * k);
    return r;
}

void DrawDiamond(Vector2 c, float r, Color col) {    Rectangle sq = { c.x - r, c.y - r, r * 2.0f, r * 2.0f };
    Vector2 tl = { sq.x, sq.y };
    Vector2 tr = { sq.x + sq.width, sq.y };
    Vector2 bl = { sq.x, sq.y + sq.height };
    Vector2 br = { sq.x + sq.width, sq.y + sq.height };
    DrawTriangle(tl, bl, tr, col);
    DrawTriangle(tr, bl, br, col);
}

void DrawRoyalPanel(Rectangle rect, Color accent) {
    const float rnd = 0.10f;
    int seg = 12;

    Rectangle sh = { rect.x + 4, rect.y + 6, rect.width, rect.height };
    DrawRectangleRounded(sh, rnd, seg, (Color){0, 0, 0, 120});

    DrawRectangleRounded(rect, rnd, seg, ROYAL_PANEL_BG);

    float cap = rect.height * 0.12f;
    if (cap > 14.0f) cap = 14.0f;
    if (cap > 4.0f) {
        Rectangle sheen = { rect.x + 10, rect.y + 4, rect.width - 20, cap };
        DrawRectangleRounded(sheen, 0.35f, 8, (Color){255, 240, 200, 16});
        Rectangle shade = { rect.x + 10, rect.y + rect.height - 4 - cap * 0.7f, rect.width - 20, cap * 0.7f };
        DrawRectangleRounded(shade, 0.35f, 8, (Color){0, 0, 0, 45});
    }

    DrawRectangleRoundedLines(rect, rnd, seg, accent);
    Rectangle b2 = { rect.x + 3, rect.y + 3, rect.width - 6, rect.height - 6 };
    DrawRectangleRoundedLines(b2, rnd, seg, Fade(accent, 0.40f));

    float m = 9.0f;
    if (rect.width > m * 6 && rect.height > m * 6) {
        Vector2 corners[4] = {
            { rect.x + m, rect.y + m },
            { rect.x + rect.width - m, rect.y + m },
            { rect.x + m, rect.y + rect.height - m },
            { rect.x + rect.width - m, rect.y + rect.height - m }
        };
        for (int i = 0; i < 4; i++) {
            DrawDiamond(corners[i], 3.6f, accent);
            DrawDiamond(corners[i], 1.6f, ScaleColor(accent, 1.5f));
        }
    }
}

void BlockUiClicks(float seconds) { if (seconds > g_uiBlock) g_uiBlock = seconds; }
void UpdateUiBlock(float dt) { if (g_uiBlock > 0) { g_uiBlock -= dt; if (g_uiBlock < 0) g_uiBlock = 0; } }

void DrawPaperPanel(Rectangle rect) {
    // soft drop shadow
    Rectangle sh = { rect.x + 5, rect.y + 8, rect.width, rect.height };
    DrawRectangleRounded(sh, 0.07f, 12, (Color){0, 0, 0, 85});
    // parchment base with subtle gradient
    DrawRectangleRounded(rect, 0.07f, 12, (Color){250, 240, 220, 255});
    Rectangle innerBg = { rect.x + 6, rect.y + 6, rect.width - 12, rect.height - 12 };
    DrawRectangleRounded(innerBg, 0.06f, 10, (Color){245, 232, 205, 255});
    // double ornate border
    DrawRectangleRoundedLines(rect, 0.07f, 12, (Color){165, 145, 110, 255});
    DrawRectangleRoundedLines(innerBg, 0.06f, 10, (Color){195, 175, 135, 200});
    // corner rosettes
    float cr = 7.0f;
    Vector2 corners[4] = {
        {rect.x + 18, rect.y + 18}, {rect.x + rect.width - 18, rect.y + 18},
        {rect.x + 18, rect.y + rect.height - 18}, {rect.x + rect.width - 18, rect.y + rect.height - 18}
    };
    for (int i = 0; i < 4; i++) {
        DrawCircleV(corners[i], cr, (Color){180, 160, 120, 255});
        DrawCircleV(corners[i], cr*0.55f, (Color){245, 235, 210, 255});
        DrawCircleV(corners[i], 2.0f, (Color){165, 145, 110, 255});
    }
    // wax seal bottom-right
    Vector2 seal = { rect.x + rect.width - 46, rect.y + rect.height - 46 };
    DrawCircleV(seal, 18, (Color){165, 45, 45, 255});
    DrawCircleV(seal, 15, (Color){185, 60, 60, 255});
    DrawCircleLines((int)seal.x, (int)seal.y, 15, (Color){120, 30, 30, 180});
    DrawCircleLines((int)seal.x, (int)seal.y, 18, (Color){90, 20, 20, 120});
    // subtle horizontal ruling
    for (int i = 0; i < 2; i++) {
        float y = rect.y + rect.height*0.32f + i * 18;
        DrawLineEx((Vector2){rect.x + 22, y}, (Vector2){rect.x + rect.width*0.62f, y}, 1.0f, Fade((Color){180,160,120,255}, 0.07f));
    }
}

void DrawTitleFlourish(Vector2 center, float width, Color accent) {
    float half = width * 0.5f;
    float gap = 12.0f;
    DrawLineEx((Vector2){center.x - half, center.y}, (Vector2){center.x - gap, center.y}, 2.0f, Fade(accent, 0.75f));
    DrawLineEx((Vector2){center.x + gap, center.y}, (Vector2){center.x + half, center.y}, 2.0f, Fade(accent, 0.75f));
    DrawLineEx((Vector2){center.x - half + 5, center.y + 4}, (Vector2){center.x - gap - 8, center.y + 4}, 1.0f, Fade(accent, 0.35f));
    DrawLineEx((Vector2){center.x + gap + 8, center.y + 4}, (Vector2){center.x + half - 5, center.y + 4}, 1.0f, Fade(accent, 0.35f));
    DrawDiamond(center, 4.5f, accent);
    DrawDiamond((Vector2){center.x - half, center.y}, 2.5f, Fade(accent, 0.85f));
    DrawDiamond((Vector2){center.x + half, center.y}, 2.5f, Fade(accent, 0.85f));
}

