void DrawFinalImage(Rectangle dst, float alpha) {
    if (!g_final_loaded) return;
    Color tint = Fade(WHITE, alpha);
    Rectangle src = { 0, 0, (float)g_final_tex.width, (float)g_final_tex.height };
    DrawTexturePro(g_final_tex, src, dst, (Vector2){0,0}, 0.0f, tint);
}

void DrawFinalImageCentered(int screenWidth, int screenHeight, float alpha) {
    if (!g_final_loaded) return;
    float texW = (float)g_final_tex.width;
    float texH = (float)g_final_tex.height;
    float maxW = screenWidth * 0.46f; // left half
    float maxH = screenHeight * 0.82f;
    float scale = fminf(maxW / texW, maxH / texH);
    float w = texW * scale;
    float h = texH * scale;
    // Editable: bottomOffset and leftMargin to move image
    float bottomOffset = 0.0f; // 0 = touches bottom
    float leftMargin = 42.0f;  // <-- change to move left/right
    Rectangle dst = { leftMargin, screenHeight - h - bottomOffset, w, h };
    DrawFinalImage(dst, alpha);
}

