void DrawPrincess(Rectangle rect, Color tint) {
    if (!g_princess_loaded) return;
    Texture2D tex = g_princess_tex;
    float srcW = (float)tex.width;
    float srcH = (float)tex.height;
    float scaleX = rect.width / srcW;
    float scaleY = rect.height / srcH;
    float scale = (scaleX < scaleY) ? scaleX : scaleY;
    float dstW = srcW * scale;
    float dstH = srcH * scale;
    float dstX = rect.x + (rect.width - dstW) * 0.5f;
    float dstY = rect.y + (rect.height - dstH) * 0.5f;
    Rectangle srcRect = { 0, 0, srcW, srcH };
    Rectangle dstRect = { dstX, dstY, dstW, dstH };
    DrawTexturePro(tex, srcRect, dstRect, (Vector2){0,0}, 0.0f, tint);
}

