void DrawWandererEx(Rectangle rect, bool hooded, Color tint) {
    if (!g_wanderer_loaded) return;
    Texture2D tex = hooded ? g_wanderer_hooded : g_wanderer_idle;
    float srcW = (float)tex.width;
    float srcH = (float)tex.height;
    float scaleX = rect.width / srcW;
    float scaleY = rect.height / srcH;
    float scale = (scaleX < scaleY) ? scaleX : scaleY;
    float characterScale = 4.0f;
    scale *= characterScale;
    float dstW = srcW * scale;
    float dstH = srcH * scale;
    float dstX = rect.x + (rect.width - dstW) * 0.5f;
    float dstY = rect.y + (rect.height - dstH) * 0.5f;
    Rectangle srcRect = { 0, 0, srcW, srcH };
    Rectangle dstRect = { dstX, dstY, dstW, dstH };
    DrawTexturePro(tex, srcRect, dstRect, (Vector2){0, 0}, 0.0f, tint);
}

void DrawWandererRevealEffect(Rectangle rect, float progress) {
    if (progress < 0) progress = 0;
    if (progress > 1) progress = 1;
    Vector2 center = { rect.x + rect.width * 0.5f, rect.y + rect.height * 0.35f };
    // Expanding golden ring
    float ringR = 25.0f + progress * 110.0f;
    DrawCircleLines((int)center.x, (int)center.y, ringR, Fade(GOLD, 0.55f * (1.0f - progress)));
    DrawCircleLines((int)center.x, (int)center.y, ringR * 0.72f, Fade(WHITE, 0.35f * (1.0f - progress)));
    // Soft flash disc
    DrawCircleV(center, 18.0f + progress * 45.0f, Fade((Color){255, 240, 180, 255}, 0.28f * (1.0f - progress)));
    // Golden dust sparkles
    for (int i = 0; i < 14; i++) {
        float a = (i * 137.5f) * DEG2RAD + progress * 1.2f;
        float d = 12.0f + (i % 4) * 18.0f + progress * 35.0f;
        float sz = 2.2f + (i % 3) * 1.1f;
        Vector2 p = { center.x + cosf(a) * d, center.y + sinf(a) * d * 0.72f };
        DrawCircleV(p, sz * (1.0f - progress * 0.5f), Fade(GOLD, 0.85f * (1.0f - progress)));
        DrawCircleV((Vector2){p.x, p.y - 1}, sz * 0.5f, Fade(WHITE, 0.9f * (1.0f - progress)));
    }
}

float EaseOutCubic(float t) {
    float u = 1 - t;
    return 1 - u*u*u;
}
float EaseOutBack(float t) {
    float c1 = 1.70158f;
    float c3 = c1 + 1;
    return 1 + c3 * powf(t - 1, 3) + c1 * powf(t - 1, 2);
}
// --- Victory gold dust ---
#define MAX_VICTORY_PARTICLES 64
typedef struct { Vector2 pos, vel; float life, maxLife; float size; float spin; Color col; } VictoryParticle;
static VictoryParticle g_vp[MAX_VICTORY_PARTICLES];
void SpawnVictoryParticles(Vector2 origin) {
    for (int i=0;i<MAX_VICTORY_PARTICLES;i++) {
        float a = GetRandomValue(0,360) * DEG2RAD;
        float sp = GetRandomValue(60, 220);
        float sz = GetRandomValue(2, 6);
        g_vp[i].pos = (Vector2){ origin.x + GetRandomValue(-12,12), origin.y + GetRandomValue(-10,10) };
        g_vp[i].vel = (Vector2){ cosf(a)*sp, sinf(a)*sp - GetRandomValue(20,60) };
        g_vp[i].life = 0;
        g_vp[i].maxLife = GetRandomValue(700, 1300)/1000.0f;
        g_vp[i].size = sz;
        g_vp[i].spin = GetRandomValue(0, 628)/100.0f;
        int pick = GetRandomValue(0,2);
        g_vp[i].col = pick==0 ? GOLD : pick==1 ? (Color){255, 215, 140, 255} : (Color){255, 240, 180, 255};
    }
    for (int i=0;i<MAX_VICTORY_PARTICLES;i++) g_vp[i].life = g_vp[i].maxLife * (0.6f + GetRandomValue(0,40)/100.0f);
}
void UpdateVictoryParticles(float dt) {
    for (int i=0;i<MAX_VICTORY_PARTICLES;i++) if (g_vp[i].life > 0) {
        g_vp[i].life -= dt;
        g_vp[i].pos.x += g_vp[i].vel.x * dt;
        g_vp[i].pos.y += g_vp[i].vel.y * dt;
        g_vp[i].vel.y += 180.0f * dt;
        g_vp[i].vel.x *= 1.0f - 0.8f*dt;
        g_vp[i].spin += dt * GetRandomValue(3, 7);
    }
}
void DrawVictoryParticles(void) {
    for (int i=0;i<MAX_VICTORY_PARTICLES;i++) if (g_vp[i].life > 0) {
        float a = g_vp[i].life / g_vp[i].maxLife;
        float s = g_vp[i].size * (0.7f + 0.6f*a);
        Color c = Fade(g_vp[i].col, a*0.95f);
        Vector2 p = g_vp[i].pos;
        // diamond sparkle
        DrawDiamond(p, s, c);
        DrawCircleV(p, s*0.45f, Fade(WHITE, a*0.55f));
    }
}
#define MAX_CURSOR_PARTICLES 80
typedef struct { Vector2 pos, vel; float life, maxLife; float size; } CursorParticle;
static CursorParticle g_cdust[MAX_CURSOR_PARTICLES];
void SpawnCursorDust(Vector2 pos) {
    for (int k=0;k<2;k++) {
        for (int i=0;i<MAX_CURSOR_PARTICLES;i++) if (g_cdust[i].life <= 0) {
            g_cdust[i].pos = (Vector2){ pos.x + GetRandomValue(-4,4), pos.y + GetRandomValue(-4,4) };
            g_cdust[i].vel = (Vector2){ GetRandomValue(-12,12)/10.0f, GetRandomValue(-18, -6)/10.0f };
            g_cdust[i].life = g_cdust[i].maxLife = GetRandomValue(400, 750)/1000.0f;
            g_cdust[i].size = GetRandomValue(14, 26)/10.0f;
            break;
        }
    }
}
void UpdateCursorParticles(float dt) {
    for (int i=0;i<MAX_CURSOR_PARTICLES;i++) if (g_cdust[i].life > 0) {
        g_cdust[i].life -= dt;
        g_cdust[i].pos.x += g_cdust[i].vel.x * dt * 18.0f + sinf(g_cdust[i].life*4 + i)*6.0f*dt;
        g_cdust[i].pos.y += g_cdust[i].vel.y * dt * 22.0f;
        g_cdust[i].vel.y += 14.0f*dt;
        g_cdust[i].vel.x *= 1.0f - 0.9f*dt;
    }
}
void DrawCursorParticles(void) {
    for (int i=0;i<MAX_CURSOR_PARTICLES;i++) if (g_cdust[i].life > 0) {
        float a = g_cdust[i].life / g_cdust[i].maxLife;
        float s = g_cdust[i].size * (0.8f + 0.4f*a);
        Color c = Fade(GOLD, a*0.9f);
        DrawDiamond(g_cdust[i].pos, s, c);
        DrawCircleV(g_cdust[i].pos, s*0.4f, Fade((Color){255,240,180,255}, a*0.6f));
    }
}

